groundTransparency = 1,\n\t\tText = "",\n\t\tAutoButtonColor = false,\n\t\tZIndex = 12,\n\t\tParent = topBar,\n\t})\n\n\tdo\n\t\tlocal isDragging = false\n\t\tlocal dragStartPos = Vector2.zero\n\t\tpcall(function()\n\t\t\tlocal sv = SlateUIState and SlateUIState.savedPositions\n\t\t\tif type(sv) ~= "table" or sv.SlateReanimWindow == nil then\n\t\t\t\tpcall(function()\n\t\t\t\t\tif type(readfile) == "function" and isfile("slate/positions.json") then\n\t\t\t\t\t\tsv = game:GetService("HttpService"):JSONDecode(readfile("slate/positions.json"))\n\t\t\t\t\tend\n\t\t\t\tend)\n\t\t\tend\n\t\t\tlocal sp = type(sv) == "table" and sv.SlateReanimWindow\n\t\t\tif type(sp) == "table" and #sp >= 4 then\n\t\t\t\tlocal d = _G.SlateClampPos(root, UDim2.new(tonumber(sp[1]) or 0.5, tonumber(sp[2]) or 0, tonumber(sp[3]) or 0.5, tonumber(sp[4]) or 0))\n\t\t\t\troot.Position = d\n\t\t\t\ttargetWindowPos = d\n\t\t\t\tdragWindowStart = d\n\t\t\t\troot:SetAttribute("SlatePosApplied", true)\n\t\t\tend\n\t\tend)\n\n\t\tdragHandle.InputBegan:Connect(function(input)\n\t\t\tif isResizing then return end\n\t\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\tisDragging = true\n\t\t\t\tdragStartPos = input.Position\n\t\t\t\tdragWindowStart = root.Position\n\t\t\t\ttargetWindowPos = root.Position\n\t\t\tend\n\t\tend)\n\n\t\tuserInputService.InputChanged:Connect(function(input)\n\t\t\tif isDragging and not isResizing and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then\n\t\t\t\tlocal delta = input.Position - dragStartPos\n\t\t\t\ttargetWindowPos = _G.SlateClampPos(root, UDim2.new(\n\t\t\t\t\tdragWindowStart.X.Scale, dragWindowStart.X.Offset + delta.X,\n\t\t\t\t\tdragWindowStart.Y.Scale, dragWindowStart.Y.Offset + delta.Y\n\t\t\t\t))\n\t\t\tend\n\t\tend)\n\n\t\tuserInputService.InputEnded:Connect(function(input)\n\t\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\tisDragging = false\n\t\t\tend\n\t\tend)\n\n\t\trunService.RenderStepped:Connect(function(dt)\n\t\t\tLPS_ATTRIBUTES(VM(NONE))\n\t\t\tif not root.Visible or isResizing then return end\n\t\t\tlocal extTarget = dragHandle:GetAttribute("TargetPos")\n\t\t\tif extTarget and not isDragging then\n\t\t\t\tdragHandle:SetAttribute("TargetPos", nil)\n\t\t\t\ttargetWindowPos = extTarget\n\t\t\tend\n\t\t\tlocal posChanged = isDragging\n\t\t\t\tor math.abs(root.Position.X.Offset - targetWindowPos.X.Offset) > 0.4\n\t\t\t\tor math.abs(root.Position.Y.Offset - targetWindowPos.Y.Offset) > 0.4\n\t\t\tif not posChanged then return end\n\t\t\tlocal lerpFactor = math.clamp(dt * 22, 0.05, 0.95)\n\t\t\tlocal newX = root.Position.X.Offset + (targetWindowPos.X.Offset - root.Position.X.Offset) * lerpFactor\n\t\t\tlocal newY = root.Position.Y.Offset + (targetWindowPos.Y.Offset - root.Position.Y.Offset) * lerpFactor\n\t\t\troot.Position = UDim2.new(targetWindowPos.X.Scale, newX, targetWindowPos.Y.Scale, newY)\n\t\tend)\n\tend\n\n\t-- Window resizing: responsive, silky-smooth drag with ergonomic corner grip\n\tdo\n\t\tlocal MIN_W, MIN_H = 310, 320\n\t\tlocal MAX_W, MAX_H = 800, 960\n\n\t\tresizeGrip = new("TextButton", {\n\t\t\tName = "ResizeGrip",\n\t\t\tAnchorPoint = Vector2.new(1, 1),\n\t\t\tPosition = UDim2.new(1, 0, 1, 0),\n\t\t\tSize = UDim2.fromOffset(26, 26),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "",\n\t\t\tAutoButtonColor = false,\n\t\t\tZIndex = 125,\n\t\t\tParent = root,\n\t\t})\n\n\t\tlocal gripIcon = new("ImageLabel", {\n\t\t\tName = "GripIcon",\n\t\t\tAnchorPoint = Vector2.new(1, 1),\n\t\t\tPosition = UDim2.new(1, -4, 1, -4),\n\t\t\tSize = UDim2.fromOffset(14, 14),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tImage = "rbxthumb://type=Asset&id=82637680965992&w=150&h=150",\n\t\t\tImageColor3 = T.text3,\n\t\t\tImageTransparency = 0.35,\n\t\t\tScaleType = Enum.ScaleType.Fit,\n\t\t\tZIndex = 126,\n\t\t\tParent = resizeGrip,\n\t\t})\n\t\ttask.spawn(function()\n\t\t\tif setIconId then\n\t\t\t\tsetIconId(gripIcon, "82637680965992")\n\t\t\telseif _G.SlateSetDecalIcon then\n\t\t\t\t_G.SlateSetDecalIcon(gripIcon, "82637680965992")\n\t\t\tend\n\t\tend)\n\n\t\tlocal function setGripVisual(state)\n\t\t\tlocal col = (state == "active" and T.accent) or (state == "hover" and T.text1) or T.text3\n\t\t\tlocal trans = (state == "active" and 0) or (state == "hover" and 0.05) or 0.35\n\t\t\ttween(gripIcon, SPRING_FAST, { ImageColor3 = col, ImageTransparency = trans })\n\t\tend\n\n\t\tresizeGrip.MouseEnter:Connect(function()\n\t\t\tif not isResizing then setGripVisual("hover") end\n\t\tend)\n\t\tresizeGrip.MouseLeave:Connect(function()\n\t\t\tif not isResizing then setGripVisual("idle") end\n\t\tend)\n\n\t\tlocal touchPointer = nil\n\t\tlocal function pointer()\n\t\t\treturn touchPointer or userInputService:GetMouseLocation()\n\t\tend\n\n\t\tlocal function setShadowSuspended(suspended)\n\t\t\tif rootShadow and rootShadow:IsA("UIShadow") then\n\t\t\t\tpcall(function() rootShadow.Transparency = suspended and 1 or 0.4 end)\n\t\t\tend\n\t\tend\n\n\t\tlocal startMouse, startW, startH, startPos = nil, 0, 0, nil\n\t\tlocal appliedW, appliedH = 0, 0\n\n\t\tlocal function applySize(w, h, withPosition)\n\t\t\tlocal cam = workspaceService.CurrentCamera\n\t\t\tlocal vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)\n\t\t\tlocal clampMaxW = math.min(MAX_W, math.max(MIN_W, vp.X - 24))\n\t\t\tlocal clampMaxH = math.min(MAX_H, math.max(MIN_H, vp.Y - 40))\n\n\t\t\tw = math.clamp(math.floor(w + 0.5), MIN_W, clampMaxW)\n\t\t\th = math.clamp(math.floor(h + 0.5), MIN_H, clampMaxH)\n\n\t\t\tif w == appliedW and h == appliedH then return end\n\t\t\tappliedW, appliedH = w, h\n\t\t\tWIN_W, WIN_H = w, h\n\n\t\t\tif not isMinimized then\n\t\t\t\troot.Size = UDim2.fromOffset(w, h)\n\t\t\t\tif rootShadow and rootShadow:IsA("GuiObject") then\n\t\t\t\t\trootShadow.Size = UDim2.fromOffset(w + 52, h + 52)\n\t\t\t\tend\n\t\t\tend\n\n\t\t\tif withPosition and startPos then\n\t\t\t\t-- Anchored at top center (0.5, 0): offset X changes by half width diff so left edge stays anchored in place\n\t\t\t\tlocal np = UDim2.new(startPos.X.Scale, startPos.X.Offset + (w - startW) / 2, startPos.Y.Scale, startPos.Y.Offset)\n\t\t\t\troot.Position = np\n\t\t\t\ttargetWindowPos = np\n\t\t\t\tdragWindowStart = np\n\t\t\t\tdragHandle:SetAttribute("TargetPos", np)\n\t\t\tend\n\t\tend\n\n\t\tresizeGrip.InputBegan:Connect(function(input)\n\t\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\tisResizing = true\n\t\t\t\ttouchPointer = input.UserInputType == Enum.UserInputType.Touch and Vector2.new(input.Position.X, input.Position.Y) or nil\n\t\t\t\tstartMouse, startW, startH, startPos = pointer(), WIN_W, WIN_H, root.Position\n\t\t\t\tappliedW, appliedH = WIN_W, WIN_H\n\t\t\t\tsetGripVisual("active")\n\t\t\t\tsetShadowSuspended(true)\n\t\t\tend\n\t\tend)\n\n\t\tuserInputService.InputChanged:Connect(function(input)\n\t\t\tif isResizing and touchPointer and input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\ttouchPointer = Vector2.new(input.Position.X, input.Position.Y)\n\t\t\tend\n\t\tend)\n\n\t\trunService.RenderStepped:Connect(function()\n\t\t\tif not isResizing then return end\n\t\t\tlocal cur = pointer()\n\t\t\tapplySize(startW + (cur.X - startMouse.X), startH + (cur.Y - startMouse.Y), true)\n\t\tend)\n\n\t\tuserInputService.InputEnded:Connect(function(input)\n\t\t\tif isResizing and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then\n\t\t\t\tisResizing = false\n\t\t\t\ttouchPointer = nil\n\t\t\t\ttargetWindowPos = root.Position\n\t\t\t\tdragWindowStart = root.Position\n\t\t\t\tsetGripVisual("idle")\n\t\t\t\tsetShadowSuspended(false)\n\t\t\t\tpcall(function()\n\t\t\t\t\tlocal sv = SlateUIState and SlateUIState.savedPositions\n\t\t\t\t\tif type(sv)